from pathlib import Path
p=Path('dist/app.js')
s=p.read_text(encoding='utf-8')
start=s.index('function home(){')
end=s.index('\nfunction players',start)
s=s[:start]+'''function home(){const year=Math.max(...D.roster.map(r=>r.season));const gs=D.games.filter(g=>g.season===year).sort((a,b)=>serial(b.date)-serial(a.date));return `<section class="season-banner"><div><div class="eyebrow">ARCHMERE ACADEMY / GIRLS VARSITY</div><h1>Volleyball<br>Record Book</h1><p>Player records, season archives and match results.</p><div class="banner-actions"><a class="button" href="#roster">Current roster →</a><a class="button secondary" href="#players">Find a player</a></div></div><div class="season-summary"><span>${year} SEASON</span><strong>${gs.filter(g=>g.result==='W').length}<i>–</i>${gs.filter(g=>g.result==='L').length}</strong><small>WINS / LOSSES</small><a href="${route('season',{year})}">Season details →</a></div></section><div class="archive-bar"><span><b>2006–2026</b> Season archive</span><span><b>${D.players.length}</b> Players</span><span><b>${D.games.length}</b> Results</span></div><div class="split"><section class="section"><div class="section-head"><h2>Latest results</h2><a class="text-link" href="${route('games',{season:year})}">All results</a></div><div class="game-list">${gs.slice(0,4).map(gameCard).join('')}</div></section><section class="section class-index"><div class="section-head"><h2>Browse by class</h2><a class="text-link" href="#players">All players</a></div><div class="class-list">${classYears().filter(y=>y!=='Unknown').sort((a,b)=>b-a).map(y=>`<a href="${route('players',{year:y})}"><span>Class of <b>${y}</b></span><small>${D.players.filter(p=>p.year===y).length} players <span aria-hidden="true">→</span></small></a>`).join('')}</div></section></div><p class="note">Reviewed records as of ${D.updated}. Historical statistics may be incomplete. <a href="#about">Sources & coverage</a></p>`}''' +s[end:]
s=s.replace("head('The players','Find a player, explore a career, or browse a graduating class.')","head('Players','Career records and game logs.')")
s=s.replace("'The players','Find a player, explore a career, or browse a graduating class.'","'Players','Career records and game logs.'")
s=s.replace("'The record lists','The top 10 documented ranks, including ties. Explore career, season and single-game leaders.'","'Record leaders','Career, season and single-game leaders. Top 10 ranks, including ties.'")
s=s.replace("eyebrow='THE RECORD BOOK'","eyebrow='ARCHMERE VOLLEYBALL'")
s=s.replace('2026 documented season totals','2026 season totals').replace('${year} documented season totals','${year} season totals')
p.write_text(s,encoding='utf-8')
p=Path('dist/index.html');s=p.read_text(encoding='utf-8');s=s.replace('<span class="crest">A<span>VOLLEYBALL</span></span>','<span class="auks-mark"><img src="archmere-athletics.jpg" alt="Archmere Auks"></span>');s=s.replace('<strong>ARCHMERE</strong><small>Girls varsity · Record book</small>','<strong>ARCHMERE</strong><small>VOLLEYBALL RECORD BOOK</small>');s=s.replace('<link rel="icon" href="icon.svg" type="image/svg+xml">','');p.write_text(s,encoding='utf-8')
